-- Generated by tools/build_supabase.py from data/schema/schema-*.sql — do not edit by hand.
-- Tables, columns, types, constraint names and CHECK expressions are copied unchanged (specs/003-sys-core R1).
-- Foreign keys follow all tables because the modules reference each other in cycles (M0 <-> M3, M4 <-> M5).

-- PROJECT: A film or content production a producer is preparing to shoot in Vietnam. (owner M0; seed file 09_project.csv)
CREATE TABLE public.project (
    project_id UUID NOT NULL,
    producer_org_id UUID NOT NULL,
    project_name VARCHAR(200) NOT NULL,
    format VARCHAR(20) NOT NULL,
    segment VARCHAR(20) NOT NULL,
    shoot_date DATE,
    buffer_days INTEGER NOT NULL,
    shoot_days_vn INTEGER,
    crew_size_band VARCHAR(20),
    logline VARCHAR(500),
    stage VARCHAR(20),
    updated_at TIMESTAMPTZ,
    CONSTRAINT pk_project PRIMARY KEY (project_id),
    CONSTRAINT ck_project_format CHECK (format IN ('feature', 'documentary', 'commercial', 'tv', 'music_video')),
    CONSTRAINT ck_project_segment CHECK (segment IN ('A', 'B', 'C')),
    CONSTRAINT ck_project_crew_size_band CHECK (crew_size_band IN ('u15', '15_50', 'o50')),
    CONSTRAINT ck_project_stage CHECK (stage IN ('draft', 'preparing', 'archived')),
    -- M2 BR-006 — the safety buffer is a number of days
    CONSTRAINT ck_project_days_not_negative CHECK (buffer_days >= 0 AND (shoot_days_vn IS NULL OR shoot_days_vn >= 0))
);

-- PROJECT_MEMBER: A person's access to one project: owner, edit or view permission. (owner M0; seed file 11_project_member.csv)
CREATE TABLE public.project_member (
    member_id UUID NOT NULL,
    project_id UUID NOT NULL,
    user_id UUID,
    invitee_email VARCHAR(254) NOT NULL,
    permission VARCHAR(20) NOT NULL,
    invite_status VARCHAR(20),
    CONSTRAINT pk_project_member PRIMARY KEY (member_id),
    CONSTRAINT ck_project_member_permission CHECK (permission IN ('owner', 'view', 'edit')),
    CONSTRAINT ck_project_member_invite_status CHECK (invite_status IN ('pending', 'accepted'))
);

-- PROJECT_PROVINCE: A province a project plans to shoot in. (owner M0; seed file 13_project_province.csv)
CREATE TABLE public.project_province (
    project_id UUID NOT NULL,
    province_id INTEGER NOT NULL,
    CONSTRAINT pk_project_province PRIMARY KEY (project_id, province_id)
);

-- READINESS_SNAPSHOT: The overall readiness of a project as recorded on one night. (owner M0; seed file 14_readiness_snapshot.csv)
CREATE TABLE public.readiness_snapshot (
    snapshot_id UUID NOT NULL,
    project_id UUID NOT NULL,
    snapshot_date DATE NOT NULL,
    readiness_total NUMERIC(5,2),
    CONSTRAINT pk_readiness_snapshot PRIMARY KEY (snapshot_id),
    -- M0 §5.1 FR-008 — a percentage
    CONSTRAINT ck_readiness_snapshot_range CHECK (readiness_total BETWEEN 0 AND 100)
);

-- READINESS_SOURCE: Whether the module behind one counted gauge currently reports to the readiness dashboard. (owner M0; seed file 15_readiness_source.csv)
CREATE TABLE public.readiness_source (
    gauge VARCHAR(20) NOT NULL,
    reporting BOOLEAN NOT NULL,
    CONSTRAINT pk_readiness_source PRIMARY KEY (gauge),
    CONSTRAINT ck_readiness_source_gauge CHECK (gauge IN ('content', 'locations', 'partners', 'dossier'))
);

-- SEGMENT_RULE: One row of the VFDA-approved decision table that maps router answers to segment A, B or C. (owner M1; seed file 07_segment_rule.csv)
CREATE TABLE public.segment_rule (
    segment_rule_id UUID NOT NULL,
    q1_shoot_in_vn BOOLEAN NOT NULL,
    q2_release VARCHAR(20),
    q3_producer VARCHAR(20),
    result_segment VARCHAR(20),
    version VARCHAR(20) NOT NULL,
    CONSTRAINT pk_segment_rule PRIMARY KEY (segment_rule_id),
    CONSTRAINT ck_segment_rule_q2_release CHECK (q2_release IN ('abroad', 'vietnam', 'both')),
    CONSTRAINT ck_segment_rule_q3_producer CHECK (q3_producer IN ('foreign', 'vietnamese', 'coproduction')),
    CONSTRAINT ck_segment_rule_result_segment CHECK (result_segment IN ('A', 'B', 'C'))
);

-- SEGMENT_REQUIREMENT: One item a segment needs or does not need, used to configure the journey and the gauges. (owner M1; seed file 08_segment_requirement.csv)
CREATE TABLE public.segment_requirement (
    segment VARCHAR(20) NOT NULL,
    requirement_code VARCHAR(40) NOT NULL,
    label_vi TEXT NOT NULL,
    label_en TEXT NOT NULL,
    needed BOOLEAN NOT NULL,
    CONSTRAINT pk_segment_requirement PRIMARY KEY (segment, requirement_code),
    CONSTRAINT ck_segment_requirement_segment CHECK (segment IN ('A', 'B', 'C'))
);

-- SEGMENT_DECISION: The segment given to a visitor or project from their answers, including any manual override. (owner M1; seed file 10_segment_decision.csv)
CREATE TABLE public.segment_decision (
    segment_decision_id UUID NOT NULL,
    project_id UUID,
    session_key VARCHAR(40),
    segment_rule_id UUID,
    q1_shoot_in_vn BOOLEAN NOT NULL,
    q2_release VARCHAR(20),
    q3_producer VARCHAR(20),
    q4_needs JSONB,
    segment VARCHAR(20),
    segment_override VARCHAR(20),
    decided_by JSONB,
    journey_config JSONB,
    CONSTRAINT pk_segment_decision PRIMARY KEY (segment_decision_id),
    CONSTRAINT ck_segment_decision_q2_release CHECK (q2_release IN ('abroad', 'vietnam', 'both')),
    CONSTRAINT ck_segment_decision_q3_producer CHECK (q3_producer IN ('foreign', 'vietnamese', 'coproduction')),
    CONSTRAINT ck_segment_decision_segment CHECK (segment IN ('A', 'B', 'C')),
    CONSTRAINT ck_segment_decision_segment_override CHECK (segment_override IN ('A', 'B', 'C')),
    -- M1 §6.1 — a decision belongs to a saved project or to an anonymous session, never both
    CONSTRAINT ck_segment_decision_one_owner CHECK ((project_id IS NULL) <> (session_key IS NULL))
);

-- MODERATION_ITEM: A partner's published content (profile text or location photo) waiting for, or carrying, VFDA staff's approve-or-hide decision. (owner M10; seed file 47_moderation_item.csv)
CREATE TABLE public.moderation_item (
    content_id UUID NOT NULL,
    content_type VARCHAR(20),
    organisation_id UUID,
    location_image_id TEXT,
    submitted_by UUID,
    submitted_at TIMESTAMPTZ,
    content_status VARCHAR(20),
    reason TEXT,
    decided_by UUID,
    decided_at TIMESTAMPTZ,
    CONSTRAINT pk_moderation_item PRIMARY KEY (content_id),
    CONSTRAINT ck_moderation_item_content_type CHECK (content_type IN ('org_profile', 'location_image', 'showcase')),
    CONSTRAINT ck_moderation_item_content_status CHECK (content_status IN ('pending', 'approved', 'hidden')),
    -- M10 §6 — exactly one target (04 Structural findings)
    CONSTRAINT ck_moderation_item_one_target CHECK ((organisation_id IS NULL) <> (location_image_id IS NULL)),
    -- M10 §5.1 FR-001 — the target matches the content type
    CONSTRAINT ck_moderation_item_target_matches_type CHECK ((content_type = 'org_profile' AND organisation_id IS NOT NULL) OR (content_type = 'location_image' AND location_image_id IS NOT NULL) OR content_type = 'showcase'),
    -- M10 BR-002 — hiding needs a reason
    CONSTRAINT ck_moderation_item_hidden_needs_reason CHECK (content_status <> 'hidden' OR reason IS NOT NULL)
);

-- AUDIT_LOG: A permanent record of one administrative action: who did what to which record, and when. (owner M10; seed file 48_audit_log.csv)
