    narrative_en TEXT,
    reread_by UUID,
    report_pdf_url TEXT,
    exported_at TIMESTAMPTZ,
    CONSTRAINT pk_quarterly_report PRIMARY KEY (report_id),
    -- M10 §5.1 FR-003 — a period
    CONSTRAINT ck_quarterly_report_period CHECK (period_end >= period_start),
    -- M10 BR-004 — no export before a reread
    CONSTRAINT ck_quarterly_report_reread_before_export CHECK (exported_at IS NULL OR reread_by IS NOT NULL)
);

