-- LOCATION: A filming location in Vietnam described and published by VFDA staff. (owner M3; seed file 22_location.csv)
CREATE TABLE public.location (
    location_id UUID NOT NULL,
    slug VARCHAR(160),
    province_id INTEGER NOT NULL,
    name_vi VARCHAR(200) NOT NULL,
    name_en VARCHAR(200) NOT NULL,
    district VARCHAR(120),
    lat NUMERIC(9,6) NOT NULL,
    lng NUMERIC(9,6) NOT NULL,
    airport_km INTEGER,
    scene_types JSONB NOT NULL,
    desc_vi TEXT NOT NULL,
    desc_en TEXT NOT NULL,
    crew_capacity VARCHAR(20) NOT NULL,
    lodging_20km BOOLEAN NOT NULL,
    grid_power BOOLEAN NOT NULL,
    truck_access BOOLEAN NOT NULL,
    months_to_avoid JSONB,
    permit_complexity VARCHAR(20) NOT NULL,
    restriction_note TEXT,
    availability VARCHAR(20) NOT NULL,
    night_shooting_allowed VARCHAR(20),
    rainy_months JSONB,
    intake_status VARCHAR(20),
    published BOOLEAN,
    blocked_reason TEXT,
    CONSTRAINT pk_location PRIMARY KEY (location_id),
    CONSTRAINT uq_location_slug UNIQUE (slug),
    CONSTRAINT ck_location_crew_capacity CHECK (crew_capacity IN ('u15', '15_50', 'o50')),
    CONSTRAINT ck_location_permit_complexity CHECK (permit_complexity IN ('low', 'medium', 'high')),
    CONSTRAINT ck_location_availability CHECK (availability IN ('open', 'survey_in_progress', 'paused')),
    CONSTRAINT ck_location_night_shooting_allowed CHECK (night_shooting_allowed IN ('yes', 'no', 'ask')),
    CONSTRAINT ck_location_intake_status CHECK (intake_status IN ('awaiting_contact', 'published', 'unpublished')),
    -- M3 BR-004, BR-008 — published only in the published state
    CONSTRAINT ck_location_published_matches_status CHECK ((CAST(published AS TEXT) = 'true') = (intake_status = 'published')),
    -- M3 §5.1 FR-002 — coordinates inside Vietnam
    CONSTRAINT ck_location_in_vietnam CHECK (lat BETWEEN 8 AND 24 AND lng BETWEEN 102 AND 110)
);

