CREATE TABLE public.bilingual_document (
    project_id UUID NOT NULL,
    doc_code VARCHAR(40) NOT NULL,
    structure_version VARCHAR(20),
    synopsis_en TEXT NOT NULL,
    project_meta JSONB NOT NULL,
    pdf_url TEXT,
    CONSTRAINT pk_bilingual_document PRIMARY KEY (project_id, doc_code)
);

-- BILINGUAL_PARAGRAPH: One aligned source/Vietnamese paragraph pair of a bilingual draft, with its proofreading status. (owner M5; seed file 41_bilingual_paragraph.csv)
CREATE TABLE public.bilingual_paragraph (
    project_id UUID NOT NULL,
    doc_code VARCHAR(40) NOT NULL,
    idx INTEGER NOT NULL,
    source_text TEXT,
    target_text TEXT,
    status VARCHAR(20),
    reviewed_by UUID,
    reviewer_org_id UUID,
    reviewed_at TIMESTAMPTZ,
    CONSTRAINT pk_bilingual_paragraph PRIMARY KEY (project_id, doc_code, idx),
    CONSTRAINT ck_bilingual_paragraph_status CHECK (status IN ('machine', 'reviewed')),
    -- M5 BR-002, FR-006 — a proofread paragraph names its proofreader
    CONSTRAINT ck_bilingual_paragraph_reviewer CHECK (status <> 'reviewed' OR reviewed_by IS NOT NULL)
);

-- PROJECT_GLOSSARY: A project's agreed translation of one term, applied to every later draft of that project. (owner M5; seed file 42_project_glossary.csv)
CREATE TABLE public.project_glossary (
    project_id UUID NOT NULL,
    term_en VARCHAR(120) NOT NULL,
    term_vi VARCHAR(120),
    CONSTRAINT pk_project_glossary PRIMARY KEY (project_id, term_en)
);

-- PUBLIC_HOLIDAY: A public holiday period shown on the licensing timeline, official or expected. (owner M5; seed file 43_public_holiday.csv)
CREATE TABLE public.public_holiday (
    name VARCHAR(120) NOT NULL,
    start_date DATE NOT NULL,
    end_date DATE NOT NULL,
    is_expected BOOLEAN NOT NULL,
    CONSTRAINT pk_public_holiday PRIMARY KEY (name, start_date),
    -- M5 §6.1 — a holiday ends on or after its first day
    CONSTRAINT ck_public_holiday_dates CHECK (end_date >= start_date)
);

-- LOCATION_INTEREST: A member's statement that a project is interested in a location. (owner M7; seed file 44_location_interest.csv)
CREATE TABLE public.location_interest (
    interest_id UUID NOT NULL,
    project_id UUID NOT NULL,
    location_id UUID NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_location_interest PRIMARY KEY (interest_id)
);

-- PROVINCE_NOTICE: The notice VFDA sends a province about a project's interest, and the province's reply. (owner M7; seed file 45_province_notice.csv)
CREATE TABLE public.province_notice (
    interest_id UUID NOT NULL,
    province_id INTEGER NOT NULL,
    project_summary TEXT NOT NULL,
    authority_email VARCHAR(254),
    drafted_at TIMESTAMPTZ NOT NULL,
    review_status VARCHAR(20),
    review_note TEXT,
    reviewed_by UUID,
    recipient VARCHAR(20),
    sent_at TIMESTAMPTZ,
    delivery_status VARCHAR(20),
    received_at TIMESTAMPTZ,
    response VARCHAR(20),
    note TEXT,
    responded_at TIMESTAMPTZ,
    response_recorded_by UUID,
    CONSTRAINT pk_province_notice PRIMARY KEY (interest_id),
    CONSTRAINT ck_province_notice_review_status CHECK (review_status IN ('draft', 'submitted', 'changes_requested', 'approved')),
    CONSTRAINT ck_province_notice_recipient CHECK (recipient IN ('peoples_committee', 'culture_department')),
    CONSTRAINT ck_province_notice_delivery_status CHECK (delivery_status IN ('queued', 'downloaded', 'sent', 'bounced')),
    CONSTRAINT ck_province_notice_response CHECK (response IN ('received', 'info_needed', 'cannot_support'))
);

-- CONSULTATION_BOOKING: A member's booked consultation slot with a VFDA officer. (owner M7; seed file 46_consultation_booking.csv)
CREATE TABLE public.consultation_booking (
    booking_id UUID NOT NULL,
    member_id UUID NOT NULL,
    topic VARCHAR(20) NOT NULL,
    preferred_times JSONB NOT NULL,
    slot_start TIMESTAMPTZ NOT NULL,
    timezone VARCHAR(40) NOT NULL,
    officer_id UUID,
    booking_status VARCHAR(20),
    CONSTRAINT pk_consultation_booking PRIMARY KEY (booking_id),
    CONSTRAINT ck_consultation_booking_topic CHECK (topic IN ('dossier', 'locations', 'partners', 'provincial_notice', 'general')),
    CONSTRAINT ck_consultation_booking_booking_status CHECK (booking_status IN ('confirmed', 'rescheduled'))
);

-- USER_ACCOUNT: A person's sign-in identity on CINEMATCH, carrying exactly one of six roles. (owner SYS; seed file 01_user_account.csv)
CREATE TABLE public.user_account (
    user_id UUID NOT NULL,
    email VARCHAR(254) NOT NULL,
    email_verified BOOLEAN,
    role VARCHAR(20) NOT NULL,
    account_status VARCHAR(20),
    created_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_user_account PRIMARY KEY (user_id),
    CONSTRAINT uq_user_account_email UNIQUE (email),
    CONSTRAINT ck_user_account_role CHECK (role IN ('guest', 'member', 'partner', 'vfda_staff', 'vfda_legal', 'admin')),
    CONSTRAINT ck_user_account_account_status CHECK (account_status IN ('active', 'deactivated'))
);

-- PRODUCER_ORGANISATION: The production company a producer signs up on behalf of. (owner SYS; seed file 02_producer_organisation.csv)
CREATE TABLE public.producer_organisation (
    producer_org_id UUID NOT NULL,
    org_name VARCHAR(200) NOT NULL,
    country CHAR(2) NOT NULL,
    website VARCHAR(300),
    CONSTRAINT pk_producer_organisation PRIMARY KEY (producer_org_id)
);

-- PROFILE: The personal details shown for an account: name, crew role and preferred language. (owner SYS; seed file 03_profile.csv)
CREATE TABLE public.profile (
    user_id UUID NOT NULL,
    full_name VARCHAR(120) NOT NULL,
    crew_role VARCHAR(22) NOT NULL,
    locale VARCHAR(20) NOT NULL,
    producer_org_id UUID,
    CONSTRAINT pk_profile PRIMARY KEY (user_id),
    CONSTRAINT ck_profile_crew_role CHECK (crew_role IN ('producer', 'director', 'production_coordinator', 'line_producer', 'other')),
    CONSTRAINT ck_profile_locale CHECK (locale IN ('vi', 'en'))
);

-- CONSENT: A record that an account accepted a given version of the terms at a given time. (owner SYS; seed file 04_consent.csv)
CREATE TABLE public.consent (
    user_id UUID NOT NULL,
    consent_version VARCHAR(20) NOT NULL,
    accepted_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_consent PRIMARY KEY (user_id, consent_version)
);

-- NOTIFICATION: An in-app message addressed to one account about one event. (owner SYS; seed file 05_notification.csv)
CREATE TABLE public.notification (
    notification_id UUID NOT NULL,
    recipient_id UUID NOT NULL,
    event_type VARCHAR(60) NOT NULL,
    payload JSONB NOT NULL,
    created_at TIMESTAMPTZ,
    read_at TIMESTAMPTZ,
    CONSTRAINT pk_notification PRIMARY KEY (notification_id)
);

-- EMAIL_DELIVERY: One transactional email handed to the email provider, with its delivery outcome. (owner SYS; seed file 06_email_delivery.csv)
CREATE TABLE public.email_delivery (
    email_delivery_id UUID NOT NULL,
    notification_id UUID,
    template_id VARCHAR(60) NOT NULL,
    recipient_email VARCHAR(254) NOT NULL,
    variables JSONB NOT NULL,
    delivery_status VARCHAR(20),
    provider_message_id TEXT,
    CONSTRAINT pk_email_delivery PRIMARY KEY (email_delivery_id),
    CONSTRAINT uq_email_delivery_provider_message_id UNIQUE (provider_message_id),
    CONSTRAINT ck_email_delivery_delivery_status CHECK (delivery_status IN ('queued', 'sent', 'bounced'))
);

